@Command([EditDocument];"1");

@If (UniType="Others" & Specify= ""; @Return(@Do(@Command([EditGotoField];"Specify") ;@Prompt([Ok];"Missing Value"; "Please enter specify before proceeding!")));"");

@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select HOD before proceeding!")));"");

@If (Remarks= ""; @Return(@Do(@Command([EditGotoField];"Remarks") ;@Prompt([Ok];"Missing Value"; "Please enter remark before proceeding!")));"");

FIELD CA := "Submitted";
FIELD Submittedby := @V3UserName;
FIELD Submittedon := @Today;
FIELD reminder1 := @Today;

@MailSend(HOD;DocAuthor;NULL;@DbTitle + " - Submitted." ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If(HODAprrov = "Approved";@SetField("CA";"HODApproved");@SetField("CA";"Rejected"));

FIELD CA := "HODApproved";
FIELD HODAprrov := "APPROVED";
FIELD HODName := @UserName;
FIELD HODDate := @Today;
FIELD reminder2 := @Today;

@MailSend(HRVer;DocAuthor;NULL;@DbTitle + " - " +  HODApprov + " by Head of Department";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

